[CmdletBinding()]
param()
$ErrorActionPreference = 'Stop'; Set-StrictMode -Version Latest
$integrator = Join-Path $PSScriptRoot 'integrate-admin-module.ps1'; $bootstrap = Join-Path $PSScriptRoot 'new-consumer.ps1'; $generator = Join-Path $PSScriptRoot 'new-admin-module.ps1'
$tooling = Split-Path -Parent (Split-Path -Parent $PSScriptRoot); $root = Join-Path ([IO.Path]::GetTempPath()) ('hoc-h4-04-' + [guid]::NewGuid().ToString('N'))
function Assert([bool]$ok,[string]$message){if(-not $ok){throw $message}}
function Fixture([string]$name){$p=Join-Path $root $name;& $bootstrap -SourceRoot $tooling -SourceSha 6a8605a63d18d35767f520d57d33193f6d15aa29 -OutputRoot $p -ApplicationId ContosoAdmin -RootUrl https://localhost:44320 -Apply|Out-Null;& $generator -ConsumerRoot $p -ApplicationId ContosoAdmin -ModuleName Products -EntityName Product -RouteSegment products -Apply|Out-Null;return $p}
function Bytes([string]$p){return ,([IO.File]::ReadAllBytes($p))}
try {
 New-Item -ItemType Directory -Path $root|Out-Null;$files=@('ContosoAdmin.slnx','src/ContosoAdmin.Web/ContosoAdmin.Web.csproj','src/ContosoAdmin.Web/ContosoAdminWebModule.cs','src/ContosoAdmin.EntityFrameworkCore/ContosoAdmin.EntityFrameworkCore.csproj','src/ContosoAdmin.EntityFrameworkCore/EntityFrameworkCore/ContosoAdminEntityFrameworkCoreModule.cs','src/ContosoAdmin.EntityFrameworkCore/EntityFrameworkCore/ContosoAdminDbContext.cs')
 $consumer=Fixture valid;$before=@{};foreach($f in $files){$before[$f]=Bytes (Join-Path $consumer $f)};& $integrator -ConsumerRoot $consumer -ApplicationId ContosoAdmin -ModuleName Products -EntityName Product;foreach($f in $files){Assert ([Linq.Enumerable]::SequenceEqual[byte]($before[$f],(Bytes (Join-Path $consumer $f)))) "Dry-run changed $f."}
 & $integrator -ConsumerRoot $consumer -ApplicationId ContosoAdmin -ModuleName Products -EntityName Product -Apply;$sln=Get-Content -Raw (Join-Path $consumer $files[0]);Assert (([regex]::Matches($sln,'modules/ContosoAdmin.Products.')).Count -eq 6) 'Solution registration failed.';$web=Get-Content -Raw (Join-Path $consumer $files[2]);Assert ($web -match 'typeof\(ProductsWebModule\)' -and $web -match 'typeof\(ProductsHttpApiModule\)') 'Web dependency composition failed.';$db=Get-Content -Raw (Join-Path $consumer $files[5]);Assert (($db -match 'DbSet<Product> Products') -and (([regex]::Matches($db,'ConfigureProducts\(\)')).Count -eq 1)) 'DbContext composition failed.'
 $after=@{};foreach($f in $files){$after[$f]=Bytes (Join-Path $consumer $f)};& $integrator -ConsumerRoot $consumer -ApplicationId ContosoAdmin -ModuleName Products -EntityName Product -Apply;foreach($f in $files){Assert ([Linq.Enumerable]::SequenceEqual[byte]($after[$f],(Bytes (Join-Path $consumer $f)))) "Second apply changed $f."}
 $fault=Fixture fault;$original=@{};foreach($f in $files){$original[$f]=Bytes (Join-Path $fault $f)};$failed=$false;try{& $integrator -ConsumerRoot $fault -ApplicationId ContosoAdmin -ModuleName Products -EntityName Product -Apply -TestFailAfterWrites 3}catch{$failed=$true};Assert $failed 'Fault injection did not fail.';foreach($f in $files){Assert ([Linq.Enumerable]::SequenceEqual[byte]($original[$f],(Bytes (Join-Path $fault $f)))) "Rollback failed for $f."}
 $missing=Fixture missing;Remove-Item (Join-Path $missing 'modules/ContosoAdmin.Products.Web/ContosoAdmin.Products.Web.csproj');$failed=$false;try{& $integrator -ConsumerRoot $missing -ApplicationId ContosoAdmin -ModuleName Products -EntityName Product -Apply}catch{$failed=$true};Assert $failed 'Missing generated project was accepted.';$failed=$false;try{& $integrator -ConsumerRoot $consumer -ApplicationId bad -ModuleName Products -EntityName Product}catch{$failed=$true};Assert $failed 'Invalid identifier was accepted.';Write-Host 'H4-04 integration self-tests passed.'
} finally {if(Test-Path $root){Remove-Item -LiteralPath $root -Recurse -Force}}
